def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            r0 = min(rr for rr, _ in cells)
            r1 = max(rr for rr, _ in cells)
            c0 = min(cc for _, cc in cells)
            c1 = max(cc for _, cc in cells)

            # An enclosed empty cell marks a hollow/frame-like object.
            box_h, box_w = r1 - r0 + 1, c1 - c0 + 1
            occupied = {(rr - r0, cc - c0) for rr, cc in cells}
            outside = set()
            todo = []
            for rr in range(box_h):
                for cc in range(box_w):
                    if rr in (0, box_h - 1) or cc in (0, box_w - 1):
                        if (rr, cc) not in occupied and (rr, cc) not in outside:
                            outside.add((rr, cc))
                            todo.append((rr, cc))
            while todo:
                rr, cc = todo.pop()
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < box_h and 0 <= nc < box_w and
                            (nr, nc) not in occupied and (nr, nc) not in outside):
                        outside.add((nr, nc))
                        todo.append((nr, nc))
            has_hole = any(
                (rr, cc) not in occupied and (rr, cc) not in outside
                for rr in range(box_h) for cc in range(box_w)
            )
            objects.append({
                "cells": cells, "color": color,
                "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                "top": has_hole
            })

    out = [[0] * w for _ in range(h)]

    def fits(obj, new_r0):
        for rr, cc in obj["cells"]:
            nr = new_r0 + rr - obj["r0"]
            if not (0 <= nr < h) or out[nr][cc] != 0:
                return False
        return True

    # Hollow objects gather at the top, preserving their vertical order.
    top_objects = sorted(
        (obj for obj in objects if obj["top"]),
        key=lambda obj: (obj["r0"], obj["c0"])
    )
    for obj in top_objects:
        height = obj["r1"] - obj["r0"] + 1
        for new_r0 in range(h - height + 1):
            if fits(obj, new_r0):
                for rr, cc in obj["cells"]:
                    out[new_r0 + rr - obj["r0"]][cc] = obj["color"]
                break

    # Plus/open objects gather at the bottom; lower original objects go last.
    bottom_objects = sorted(
        (obj for obj in objects if not obj["top"]),
        key=lambda obj: (-obj["r1"], obj["c0"])
    )
    for obj in bottom_objects:
        height = obj["r1"] - obj["r0"] + 1
        for new_r0 in range(h - height, -1, -1):
            if fits(obj, new_r0):
                for rr, cc in obj["cells"]:
                    out[new_r0 + rr - obj["r0"]][cc] = obj["color"]
                break

    return out
